use std::fs
use std::collections::HashMap

struct Row {
    name: string,
    total: int,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut bad = 0
    let mut totals: HashMap<string, int> = HashMap::new()
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut acts: HashMap<string, int> = HashMap::new()
    let mut users: Vec<string> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() != 3 {
            bad += 1
            continue
        }
        let u = parts[0]
        let a = parts[1]
        let s = parts[2]
        let mut ok = s.len() > 0
        for c in s.chars() {
            if !c.is_ascii_digit() { ok = false }
        }
        if !ok {
            bad += 1
            continue
        }
        let n: int = s.parse::<int>().unwrap_or(0)
        if !totals.contains_key(u) {
            users.push(u)
            totals.insert(u, 0)
            counts.insert(u, 0)
        }
        totals.insert(u, totals.get(u).unwrap_or(0) + n)
        counts.insert(u, counts.get(u).unwrap_or(0) + 1)
        let key = "${u} ${a}"
        acts.insert(key, acts.get(key).unwrap_or(0) + 1)
    }
    let mut rows: Vec<Row> = []
    for u in users {
        rows.push(Row { name: u, total: totals.get(u).unwrap_or(0) })
    }
    rows.sort_by(|x, y| {
        if x.total != y.total {
            return y.total.cmp(x.total)
        }
        return x.name.cmp(y.name)
    })
    for r in rows {
        let u = r.name
        let mut best = ""
        let mut bc = 0
        for k in acts.keys() {
            let pre = "${u} "
            if k.starts_with(pre) {
                let a = k[pre.len()..k.len()]
                let c: int = acts[k]
                let better = c > bc
                let tie = c == bc && a < best
                if better || tie {
                    bc = c
                    best = a
                }
            }
        }
        println("${u} ${counts.get(u).unwrap_or(0)} ${totals.get(u).unwrap_or(0)} ${best}")
    }
    println("malformed: ${bad}")
}

